const base = $('Dados da agenda').first().json;
const google = $input.first().json;
const TZ = 'America/Sao_Paulo';
const esc = base.escritorio, resp = base.responsavel;
const pedido = $('Chamado pela IA').first().json;

if (!resp) return [{ json: { resposta: 'Não há advogado disponível para reuniões cadastrado. Use transferir_para_humano.' } }];

const ocupados = (base.ocupados || []).map(([i, f]) => [DateTime.fromISO(i).toMillis(), DateTime.fromISO(f).toMillis()]);
if (base.calendar_id) {
  const cal = google?.calendars?.[base.calendar_id];
  if (cal && !cal.errors) ocupados.push(...(cal.busy || []).map(b => [DateTime.fromISO(b.start).toMillis(), DateTime.fromISO(b.end).toMillis()]));
}

const dur = esc.duracao_reuniao_min, folga = esc.intervalo_entre_reunioes_min * 60000;
const nomesDia = [null, 'seg', 'ter', 'qua', 'qui', 'sex', 'sab', 'dom'];
const agora = DateTime.now().setZone(TZ);
const minimo = agora.plus({ hours: esc.antecedencia_minima_horas });
const limite = agora.startOf('day').plus({ days: esc.dias_para_frente });
let dia = pedido.data_inicial ? DateTime.fromISO(pedido.data_inicial, { zone: TZ }).startOf('day') : agora.startOf('day');
if (!dia.isValid || dia < agora.startOf('day')) dia = agora.startOf('day');
const periodo = String(pedido.periodo || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

const livres = [];
for (; dia <= limite && livres.length < 60; dia = dia.plus({ days: 1 })) {
  let faixas = esc.horario_atendimento?.[nomesDia[dia.weekday]] || [];
  if (faixas.length && !Array.isArray(faixas[0])) faixas = [faixas];
  for (const [ini, fim] of faixas) {
    const [hi, mi] = ini.split(':').map(Number), [hf, mf] = fim.split(':').map(Number);
    const fimFaixa = dia.set({ hour: hf, minute: mf });
    for (let s = dia.set({ hour: hi, minute: mi }); s.plus({ minutes: dur }) <= fimFaixa; s = s.plus({ minutes: 30 })) {
      const f = s.plus({ minutes: dur });
      const okPeriodo = !periodo || periodo === 'qualquer' || (periodo.startsWith('manh') && s.hour < 12) || (periodo === 'tarde' && s.hour >= 12 && s.hour < 18) || (periodo === 'noite' && s.hour >= 18);
      const conflito = ocupados.some(([oi, of]) => s.toMillis() < of + folga && f.toMillis() + folga > oi);
      if (s >= minimo && okPeriodo && !conflito) livres.push(s);
    }
  }
}

if (!livres.length) {
  return [{ json: { resposta: `Não há horários livres com ${resp.nome} nesse período (próximos ${esc.dias_para_frente} dias). Pergunte se o cliente aceita outro período ou ofereça transferir_para_humano.` } }];
}

// até 6 opções espalhadas: no máximo 2 por dia, em até 3 dias diferentes
const porDia = {};
for (const s of livres) (porDia[s.toISODate()] ||= []).push(s);
const opcoes = [];
for (const lista of Object.values(porDia).slice(0, 3)) {
  opcoes.push(lista[0]);
  const outra = lista.find(s => Math.abs(s.hour - lista[0].hour) >= 3) || lista[1];
  if (outra) opcoes.push(outra);
}
const linhas = opcoes.map(s => `- ${s.setLocale('pt-BR').toFormat("cccc, dd/MM 'às' HH:mm")} -> inicio=${s.toISO({ suppressMilliseconds: true })}`);
return [{ json: {
  resposta: `Horários livres com ${resp.nome} (reunião de ${dur} minutos):\n${linhas.join('\n')}\nresponsavel_id=${resp.id}\nOfereça 2 ou 3 destas opções ao cliente, de forma natural (não mostre os valores inicio/responsavel_id).`,
}}];
